const data = require('fs').readFileSync(0, 'utf8').split(/\s+/).filter(Boolean).map(Number);
const n = data[0];
const m = data[1];
const edges = Array.from({ length: n }, () => []);
const indegree = new Array(n).fill(0);
for (let i = 0; i < m; i++) {
  const a = data[2 + i * 2];
  const b = data[3 + i * 2];
  edges[a].push(b);
  indegree[b]++;
}

// Smallest-first binary heap of the services whose dependencies are all met.
const ready = [];
function push(v) {
  ready.push(v);
  let i = ready.length - 1;
  while (i > 0) {
    const parent = (i - 1) >> 1;
    if (ready[parent] <= ready[i]) break;
    [ready[parent], ready[i]] = [ready[i], ready[parent]];
    i = parent;
  }
}
function pop() {
  const top = ready[0];
  const last = ready.pop();
  if (ready.length) {
    ready[0] = last;
    let i = 0;
    for (;;) {
      const left = i * 2 + 1;
      const right = left + 1;
      let least = i;
      if (left < ready.length && ready[left] < ready[least]) least = left;
      if (right < ready.length && ready[right] < ready[least]) least = right;
      if (least === i) break;
      [ready[least], ready[i]] = [ready[i], ready[least]];
      i = least;
    }
  }
  return top;
}

for (let v = 0; v < n; v++) if (indegree[v] === 0) push(v);
const order = [];
while (ready.length) {
  const v = pop();
  order.push(v);
  for (const w of edges[v]) if (--indegree[w] === 0) push(w);
}
console.log(order.length !== n ? 'cycle' : order.join('\n'));

package main

import (
	"bufio"
	"container/heap"
	"fmt"
	"os"
	"strconv"
)

type minHeap []int

func (h minHeap) Len() int            { return len(h) }
func (h minHeap) Less(i, j int) bool  { return h[i] < h[j] }
func (h minHeap) Swap(i, j int)       { h[i], h[j] = h[j], h[i] }
func (h *minHeap) Push(x any)         { *h = append(*h, x.(int)) }
func (h *minHeap) Pop() any           { old := *h; v := old[len(old)-1]; *h = old[:len(old)-1]; return v }

func main() {
	in := bufio.NewReader(os.Stdin)
	var n, m int
	if _, err := fmt.Fscan(in, &n, &m); err != nil {
		return
	}
	edges := make([][]int, n)
	indegree := make([]int, n)
	for i := 0; i < m; i++ {
		var a, b int
		if _, err := fmt.Fscan(in, &a, &b); err != nil {
			break
		}
		edges[a] = append(edges[a], b)
		indegree[b]++
	}
	ready := &minHeap{}
	for v := 0; v < n; v++ {
		if indegree[v] == 0 {
			*ready = append(*ready, v)
		}
	}
	heap.Init(ready)
	order := make([]int, 0, n)
	for ready.Len() > 0 {
		v := heap.Pop(ready).(int)
		order = append(order, v)
		for _, w := range edges[v] {
			indegree[w]--
			if indegree[w] == 0 {
				heap.Push(ready, w)
			}
		}
	}
	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	if len(order) != n {
		out.WriteString("cycle\n")
		return
	}
	for _, v := range order {
		out.WriteString(strconv.Itoa(v))
		out.WriteByte('\n')
	}
}

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.StreamTokenizer;
import java.util.ArrayList;
import java.util.List;
import java.util.PriorityQueue;

public class Main {
    public static void main(String[] args) throws Exception {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        if (in.nextToken() == StreamTokenizer.TT_EOF) return;
        int n = (int) in.nval;
        in.nextToken();
        int m = (int) in.nval;
        List<List<Integer>> edges = new ArrayList<>();
        for (int i = 0; i < n; i++) edges.add(new ArrayList<>());
        int[] indegree = new int[n];
        for (int i = 0; i < m; i++) {
            in.nextToken();
            int a = (int) in.nval;
            in.nextToken();
            int b = (int) in.nval;
            edges.get(a).add(b);
            indegree[b]++;
        }
        PriorityQueue<Integer> ready = new PriorityQueue<>();
        for (int v = 0; v < n; v++) if (indegree[v] == 0) ready.add(v);
        StringBuilder out = new StringBuilder();
        int seen = 0;
        while (!ready.isEmpty()) {
            int v = ready.poll();
            seen++;
            out.append(v).append('\n');
            for (int w : edges.get(v)) if (--indegree[w] == 0) ready.add(w);
        }
        System.out.print(seen != n ? "cycle\n" : out);
    }
}

