import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.StreamTokenizer;

public class Main {
    static int[] weights;

    public static void main(String[] args) throws Exception {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int n = (int) in.nval;
        in.nextToken();
        int k = (int) in.nval;
        weights = new int[n];
        long lo = 0;
        long hi = 0;
        for (int i = 0; i < n; i++) {
            in.nextToken();
            weights[i] = (int) in.nval;
            lo = Math.max(lo, weights[i]);
            hi += weights[i];
        }
        while (lo < hi) {
            long mid = (lo + hi) / 2;
            if (trucksNeeded(mid) <= k) hi = mid;
            else lo = mid + 1;
        }
        System.out.println(lo);
    }

    static int trucksNeeded(long cap) {
        int used = 1;
        long load = 0;
        for (int w : weights) {
            if (load + w > cap) {
                used++;
                load = w;
            } else {
                load += w;
            }
        }
        return used;
    }
}
